import assert from 'node:assert/strict';
import {randomBytes,randomUUID} from 'node:crypto';
import {readFileSync} from 'node:fs';
import {createOuchiFamilyPreparationGeneration} from '../../../lib/ouchi-family-preparation-generation.mjs';
import {createDeletionJournal} from '../kakei-completion/lib/shared-deletion-journal.mjs';
export async function verifyFamilyPreparationGenerations({admin,coordinator,auth,transaction}){
 await admin.query(readFileSync('tests/fixtures/family-preparation-generations-20261021/protocol.sql','utf8'));
 const person=async()=>{const user=randomUUID(),epoch=randomUUID(),password=randomBytes(30).toString('base64url'),email=user+'@fixture.invalid';await auth.createFixtureUser(user,email,password);const login=await auth.request('/token?grant_type=password',{email,password});const sid=JSON.parse(Buffer.from(login.access_token.split('.')[1],'base64url')).session_id;
 await admin.query('insert into maintenance_private.account_access values($1,true)',[user]);await admin.query('insert into maintenance_private.app_epochs values($1,$2,true)',[user,epoch]);await admin.query('insert into maintenance_private.app_session_epochs values($1,$2,$3)',[sid,user,epoch]);return {user,epoch};};
 const owner=await person(),receiver=await person(),home=randomUUID(),product=randomUUID();
 await admin.query('insert into public.homes(id,owner_id) values($1,$2)',[home,owner.user]);await admin.query('insert into public.home_members("homeId",user_id,nickname) values($1,$2,$3)',[home,receiver.user,'Generation receiver']);await admin.query('insert into public.products(id,"homeId","categoryId",name) values($1,$2,$3,$4)',[product,home,'air','Family generation retained']);
 await admin.query((await admin.query("select format('create policy family_generation_%s on private.kb_shared_deletion_journal for all to shared_retirement_backend using(user_id=%L::uuid) with check(user_id=%L::uuid)',replace($1::text,'-',''),$1::text,$1::text) sql",[owner.user])).rows[0].sql);
 const originalEvidence=(await admin.query('select * from maintenance_private.ouchi_owner_originals order by request_id')).rows;
 const oldPlans=(await admin.query('select * from maintenance_private.household_handoff_plans order by home_id')).rows;
 const family=(await admin.query('select * from public.homes where id=$1',[home])).rows;
 const data=(await admin.query('select * from public.products where id=$1',[product])).rows;
 const make=async()=>{const scope={protocolVersion:2,kind:'shared-account',requestID:randomUUID(),userID:owner.user,leaseToken:randomUUID(),inventoryDigest:'8'.repeat(64),apps:[{app:'ouchi-maintenance',requestID:randomUUID(),scopeID:owner.epoch}]};const fixed={...scope};delete fixed.leaseToken;await admin.query("insert into private.kb_shared_deletion_journal values($1,$2,$3,'requested',null,null,'{}')",[scope.requestID,owner.user,fixed]);return {scope,generationID:randomUUID(),nativeLease:randomUUID(),homes:[{homeID:home,successorID:receiver.user}]};};
 let available=true;
 const port=x=>createOuchiFamilyPreparationGeneration({...x,verifyNoDispatch:async(s,tx,signal)=>{signal.throwIfAborted();return available&&JSON.stringify(s)===JSON.stringify(x.scope);}});
 const first=await make(),f=port(first);
 const wrongRoster=port({...first,homes:[{homeID:randomUUID(),successorID:receiver.user}]});
 await assert.rejects(transaction(coordinator,tx=>wrongRoster.reserve(first.scope,tx)),/Complete current family roster/);
 await assert.rejects(transaction(coordinator,async tx=>{await f.reserve(first.scope,tx);available=false;}),/Current transaction verification/);available=true;
 assert.equal((await admin.query('select count(*)::int n from maintenance_private.family_preparation_generations where generation_id=$1',[first.generationID])).rows[0].n,0,'Late coverage rolls all reservation history/pointers back');
 assert.equal(await transaction(coordinator,tx=>f.reserve(first.scope,tx)),true);assert.equal(await transaction(coordinator,tx=>f.reserve(first.scope,tx)),true,'Lost reply retries same history');
 const saved=(await admin.query('select * from maintenance_private.family_preparation_generations where generation_id=$1',[first.generationID])).rows;
 const roster=saved[0].roster;assert.equal(roster.length,1);assert.deepEqual(roster[0].members.map(x=>x.actorID).sort(),[owner.user,receiver.user].sort());assert.ok(roster[0].members.every(x=>x.epochID&&x.sessions.length));
 const conflicting={...first,generationID:randomUUID()},conflictingPort=port(conflicting);
 await assert.rejects(transaction(coordinator,tx=>conflictingPort.reserve(conflicting.scope,tx)),/operation unconfirmed/);
 await assert.rejects(transaction(coordinator,async tx=>{await tx.query("update private.kb_shared_deletion_journal set status='processing',lease_token=$2,lease_until=clock_timestamp()+interval '1 minute' where request_id=$1",[first.scope.requestID,first.scope.leaseToken]);await f.cancelRequested(first.scope,tx);}),/Exact requested\/cancelled generation root/);
 const journal=createDeletionJournal({transaction:work=>transaction(coordinator,work)},{'after-cancel':(s,tx)=>f.cancelRequested(s,tx)});
 await assert.rejects(transaction(coordinator,async tx=>{await tx.query("update private.kb_shared_deletion_journal set status='cancelled' where request_id=$1",[first.scope.requestID]);await f.cancelRequested(first.scope,tx);available=false;}),/Current transaction verification/);available=true;
 assert.equal((await admin.query('select generation_id from maintenance_private.current_family_preparation_generations where home_id=$1',[home])).rows[0].generation_id,first.generationID);
 assert.equal(await journal.cancel(first.scope),true);
 const next=await make(),g=port(next);
 assert.equal(await transaction(coordinator,tx=>g.reserve(next.scope,tx)),true,'Same retained home, new root and generation succeed without deleting old history');
 assert.equal(await transaction(coordinator,tx=>f.cancelRequested(first.scope,tx)),true,'Old cancellation is historical and does not release a new generation');
 assert.equal((await admin.query('select generation_id from maintenance_private.current_family_preparation_generations where home_id=$1',[home])).rows[0].generation_id,next.generationID);
 assert.deepEqual((await admin.query('select * from maintenance_private.family_preparation_generations where generation_id=$1',[first.generationID])).rows,saved);
 await assert.rejects(admin.query('update maintenance_private.family_preparation_generations set targets=\'[]\' where generation_id=$1',[first.generationID]),/Immutable/);
 await assert.rejects(admin.query('delete from maintenance_private.family_preparation_generations where generation_id=$1',[first.generationID]),/Immutable/);
 const receiverEpoch=randomUUID();await admin.query('update maintenance_private.app_epochs set epoch_id=$2 where user_id=$1',[receiver.user,receiverEpoch]);
 const epochJournal=createDeletionJournal({transaction:work=>transaction(coordinator,work)},{'after-cancel':(s,tx)=>g.cancelRequested(s,tx)});
 await assert.rejects(epochJournal.cancel(next.scope),/Changed\/prepared\/dispatched/);
 assert.equal((await admin.query('select epoch_id from maintenance_private.app_epochs where user_id=$1',[receiver.user])).rows[0].epoch_id,receiverEpoch);
 await admin.query('update maintenance_private.app_epochs set epoch_id=$2 where user_id=$1',[receiver.user,receiver.epoch]);
 // Durable unknown dispatch is an admission record, not a successful result.
 await admin.query("insert into maintenance_private.family_preparation_dispatches values($1,'copy','unknown')",[next.generationID]);
 const nextJournal=createDeletionJournal({transaction:work=>transaction(coordinator,work)},{'after-cancel':(s,tx)=>g.cancelRequested(s,tx)});
 await assert.rejects(nextJournal.cancel(next.scope),/Changed\/prepared\/dispatched/);
 assert.equal((await admin.query('select status from private.kb_shared_deletion_journal where request_id=$1',[next.scope.requestID])).rows[0].status,'requested');
 assert.equal((await admin.query('select generation_id from maintenance_private.current_family_preparation_generations where home_id=$1',[home])).rows[0].generation_id,next.generationID);
 assert.deepEqual((await admin.query('select * from maintenance_private.ouchi_owner_originals order by request_id')).rows,originalEvidence,'Actual earlier signed owner originals preserved byte-for-byte');
 assert.deepEqual((await admin.query('select * from maintenance_private.household_handoff_plans order by home_id')).rows,oldPlans,'No legacy plan overwrite/DELETE or key/guard changes');
 assert.deepEqual((await admin.query('select * from public.homes where id=$1',[home])).rows,family);assert.deepEqual((await admin.query('select * from public.products where id=$1',[product])).rows,data);
 await assert.rejects(coordinator.query('select * from maintenance_private.family_preparation_generations'),/permission denied/);
 console.log('Family preparation generation reservation: real enrolled full family roster/preimage, same-home new-root append-only history, current-generation conflict and old-cancel isolation, immutable earlier originals/plans, late rollback and unknown-copy dispatch refusal pass. NO native preparation, write-stop, new family consent issuance, file handling or claim/activation authority is implemented by this reservation gate. Hosted profile/retention/remaining-path admission unapproved.');
}
